CREATE OR REPLACE FUNCTION public.get_companies_with_employee_permission(permission text)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  permission_companies text[];
  api_key_company text;
  employee_companies text[];
  api_key_scopes JSONB;
BEGIN
  api_key_company := get_company_id_from_api_key();

  IF api_key_company IS NOT NULL THEN
    api_key_scopes := get_api_key_scopes();
    IF api_key_scopes IS NULL OR api_key_scopes = '{}'::jsonb THEN
      RETURN '{}';
    END IF;
    IF (api_key_scopes ? permission)
       AND api_key_company = ANY(jsonb_to_text_array(api_key_scopes->permission)) THEN
      RETURN ARRAY[api_key_company];
    ELSE
      RETURN '{}';
    END IF;
  END IF;

  SELECT array_agg("companyId"::text)
  INTO employee_companies
  FROM "userToCompany"
  WHERE "userId" = auth.uid()::text AND "role" = 'employee';

  SELECT jsonb_to_text_array(COALESCE(permissions->permission, '[]'))
  INTO permission_companies
  FROM public."userPermission"
  WHERE id::text = auth.uid()::text;

  IF permission_companies IS NOT NULL AND employee_companies IS NOT NULL THEN
    SELECT array_agg(company)
    INTO permission_companies
    FROM unnest(permission_companies) company
    WHERE company = ANY(employee_companies);
  ELSE
    permission_companies := '{}';
  END IF;

  RETURN COALESCE(permission_companies, '{}');
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_companies_with_permission(permission text)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  permission_companies text[];
  api_key_company text;
  api_key_scopes jsonb;
BEGIN
  -- Deprecated: prefer get_companies_with_employee_permission. Unlike it, this also admits
  -- customer and supplier (portal) members, which the portal's document access relies on.

  -- An API key holds only the permissions its scopes grant, in its own company.
  api_key_company := get_company_id_from_api_key();
  IF api_key_company IS NOT NULL THEN
    api_key_scopes := get_api_key_scopes();
    IF api_key_scopes ? permission
       AND api_key_company = ANY(jsonb_to_text_array(api_key_scopes->permission)) THEN
      RETURN ARRAY[api_key_company];
    END IF;
    RETURN '{}';
  END IF;

  -- A user holds a permission only in companies they belong to. There is no '0' wildcard:
  -- it used to expand to every company on the instance.
  SELECT array_agg(company)
  INTO permission_companies
  FROM public."userPermission" up,
       unnest(jsonb_to_text_array(COALESCE(up.permissions->permission, '[]'))) company
  WHERE up.id = auth.uid()::text
    AND EXISTS (
      SELECT 1 FROM "userToCompany" utc
      WHERE utc."userId" = auth.uid()::text AND utc."companyId" = company
    );

  RETURN COALESCE(permission_companies, '{}');
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_company_id_from_foreign_key(foreign_key text, tbl text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    DECLARE
      company_id text;
    BEGIN
      -- Policies call this inside a query. Called as the API endpoint itself it would tell
      -- anyone holding the anon key which company owns any row id, so refuse that. PostgREST
      -- sets request.path to /rpc/<function> only for a direct call (any case, any trailing /).
      IF current_setting('request.path', true) ~* '/rpc/get_company_id_from_foreign_key/*$' THEN
        RAISE EXCEPTION 'get_company_id_from_foreign_key cannot be called through the API'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      EXECUTE format('SELECT "companyId" FROM %I WHERE id = $1', tbl) INTO company_id USING foreign_key;
      RETURN company_id;
    END;
$function$;

CREATE OR REPLACE FUNCTION public.get_permission_companies(claim text)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    DECLARE
      retval text[];
    BEGIN
      -- Deprecated: prefer get_companies_with_employee_permission. A permission counts only in
      -- a company the caller belongs to; no API key path (keys get nothing, as before).
      SELECT array_agg(company)
      INTO retval
      FROM public."userPermission" up,
           unnest(jsonb_to_text_array(COALESCE(up.permissions->claim, '[]'))) company
      WHERE up.id = auth.uid()::text
        AND EXISTS (
          SELECT 1 FROM "userToCompany" utc
          WHERE utc."userId" = auth.uid()::text AND utc."companyId" = company
        );
      RETURN retval;
    END;
$function$;

CREATE OR REPLACE FUNCTION public.has_company_permission(claim text, company text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    BEGIN
      -- Deprecated (still used by storage policies). True only when the caller holds the
      -- permission in that company AND belongs to it.
      RETURN EXISTS (
        SELECT 1
        FROM public."userPermission" up
        WHERE up.id = (SELECT auth.uid()::text)
          AND company = ANY(jsonb_to_text_array(COALESCE(up.permissions->claim, '[]')))
      ) AND EXISTS (
        SELECT 1 FROM "userToCompany" utc
        WHERE utc."userId" = (SELECT auth.uid()::text) AND utc."companyId" = company
      );
    END;
$function$;

